class Solution {
public:
    int maxDepthBST(vector<int>& order) {
        map<int, int> depth;
        int answer = 0;
        for (int value : order) {
            auto it = depth.lower_bound(value);
            int left = 0, right = 0;
            if (it != depth.end()) {
                right = it->second;
            }
            if (it != depth.begin()) {
                left = prev(it)->second;
            }
            int d = max(left, right) + 1;
            depth[value] = d;
            answer = max(answer, d);
        }
        return answer;
    }
};
